<template>
  <view class="sm-stack workflow-editor">
    <view v-if="loading" class="sm-state">正在引用原巡检，准备七类核对…</view>
    <view v-else-if="error" class="sm-alert sm-alert--error">{{ error }}<button class="sm-btn sm-btn--secondary" @click="load">重新加载七类核对</button><text class="sm-help">原36项巡检已保存，不受此处加载或保存失败影响。</text></view>
    <template v-else>
      <view class="sm-card"><view class="sm-section-head"><text class="sm-h2">第二步 · 七类核对</text><text class="sm-tag">{{ data.inspection?.inspection_no }}</text></view><text class="sm-help">已有检查自动引用；确认有相关作业才展开。未开展、不适用分别记录，不计作正常。可分次暂存，签字最后处理。</text><label class="sm-field"><text class="sm-field-label">本次事实截至时间（北京时间） *</text><input v-model="observedText" class="sm-input" :disabled="readonly" placeholder="YYYY-MM-DD HH:mm" /></label><text class="sm-help">“无”仅表示截至上述时刻未开展。后续开展作业，请更新事实时刻并增加记录；旧版保留。</text><text v-if="readonly" class="sm-alert sm-alert--info">当前账号可查看。本巡检本人可录入本次事实；他人补齐及核对日表按厂站岗位权限校验。</text></view>
      <view v-if="sameDaySource" class="sm-card"><text class="sm-h3">当天已有作业资料可引用</text><text class="sm-help">来源：{{ sameDaySource.inspection_id }} · {{ sameDaySource.observed_by_name }} · 截至 {{ formatDateTime(sameDaySource.observed_at) }}。引用已发生的作业及报告；“无”的判断、本班人员、临时措施仍需本次确认。</text><button v-if="!readonly" class="sm-btn sm-btn--secondary" @click="copySameDay">引用当天已发生的作业资料</button><text v-for="source in workflow.reference_sources || []" :key="source.inspection_id" class="sm-help">已引用：{{ source.inspection_id }} · {{ formatDateTime(source.observed_at) }}</text></view>
      <view class="sm-card"><text class="sm-h2">截至本次巡检的作业与报告</text><view v-for="activity in activityOptions" :key="activity.key" class="workflow-switch"><text class="sm-field-label">{{ activity.label }} *</text><WorkflowChoice v-model="workflow.activities[activity.key]" :disabled="readonly" /><text class="sm-help">{{ activity.help }}</text></view><text class="sm-help">装卸有无只确认一次，同步控制第2、3、4类；充装或收发会展开第6类标签检查。所有选项均需主动确认。</text></view>
      <view class="sm-tabs"><view v-for="category in categories" :key="category.id" :class="['sm-tab',{'sm-tab--active':activeCategory===category.id}]" @click="activeCategory=category.id">{{ category.id }}．{{ category.name }}{{ categoryPendingCount(category.id)?` · 待核${categoryPendingCount(category.id)}组`:'' }}</view></view>
      <view v-for="category in categories" v-show="activeCategory===category.id" :key="category.id" class="sm-stack">
        <view class="sm-card"><text class="sm-h2">{{ category.id }}．{{ category.name }}</text><text class="sm-help">原巡检本类 {{ originalChecks(category.id).length }} 项，已有结果直接引用。</text><view v-for="item in originalChecks(category.id)" :key="item.item_code" class="workflow-reference"><text class="sm-tag">{{ labels[item.result_code] || '待检查' }}</text><text class="sm-text">{{ item.item_label_snapshot || item.item_label || item.label }}</text></view><text class="sm-link" @click="openInspection(inspectionId)">查看原36项及现场照片</text></view>
        <view v-for="coverage in categoryCoverage(category.id)" :key="coverage.code" class="sm-card"><text class="sm-h3">{{ coverage.label }}</text><template v-if="coverage.status==='covered'"><text class="sm-tag sm-tag--good">原巡检已覆盖 · 不重复计数</text><text v-for="reference in coverage.source_refs" :key="reference.item_code" class="sm-help">{{ reference.label }} · {{ labels[reference.result_code] || '待核实' }}</text></template><template v-else><text class="sm-alert">本次原巡检尚未覆盖此检查范围，请依据真实检查补齐。旧模板正常结果不能推定已检查新增范围。</text><WorkflowCheckFields :item="check(coverage.code)" :fields="checkFields[coverage.code] || []" :inspection-id="inspectionId" :date="data.inspection?.inspection_date" :code="coverage.code" :category="category.id" :readonly="readonly" :hazards="data.open_hazards || []" @busy="setBusy(coverage.code,$event)" @issue-saved="issueSaved" /></template></view>
        <template v-if="category.id===1">
          <view v-for="type in specialWorkTypes" :key="type.code" class="sm-card"><text class="sm-h3">{{ type.label }} *</text><WorkflowChoice :model-value="special(type.code).conducted" :disabled="readonly" @update:model-value="chooseSpecial(type.code,$event)" /><text v-if="special(type.code).conducted==='no'" class="sm-help">截至本次巡检未开展；吊秤、防脱钩仍引用原第22项。</text>
            <template v-if="special(type.code).conducted==='yes'"><view v-for="(event,index) in special(type.code).events" :key="event.id" class="workflow-event"><view class="sm-section-head"><text class="sm-h3">{{ type.label }} · 第{{ index+1 }}次</text><button v-if="!readonly && !savedEvent(event.id)" class="sm-btn sm-btn--secondary sm-btn--small" @click="removeEvent(type.code,index)">移除此条</button></view><label v-if="type.code==='other'" class="sm-field"><text class="sm-field-label">实际作业名称 *</text><input v-model="event.name" class="sm-input" :disabled="readonly" /></label><label class="sm-field"><text class="sm-field-label">作业地点 *</text><input v-model="event.location" class="sm-input" :disabled="readonly" /></label><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">开始时间 *</text><input :value="timeText(event.started_at)" class="sm-input" :disabled="readonly" placeholder="YYYY-MM-DD HH:mm" @input="event.started_at=$event.detail.value" /></label><label class="sm-field"><text class="sm-field-label">结束时间（未结束可留空）</text><input :value="timeText(event.ended_at)" class="sm-input" :disabled="readonly" placeholder="YYYY-MM-DD HH:mm" @input="event.ended_at=$event.detail.value" /></label></view><label v-for="field in specialFields" :key="field.key" class="sm-field"><text class="sm-field-label">{{ field.label }} *</text><textarea v-model="event[field.key]" class="sm-textarea" :disabled="readonly" /></label><WorkflowCheckFields :item="event" :inspection-id="inspectionId" :date="data.inspection?.inspection_date" :code="'S01'" :category="1" :readonly="readonly" :hazards="data.open_hazards || []" @busy="setBusy(event.id,$event)" @issue-saved="issueSaved" /></view><button v-if="!readonly" class="sm-btn sm-btn--secondary sm-btn--small" @click="special(type.code).events.push(newSpecialEvent())">增加一次{{ type.label }}</button></template>
          </view>
        </template>
        <template v-if="category.id===2">
          <view class="sm-card"><text class="sm-h3">安全附件、仪表证书核验</text><text class="sm-help">逐设备展示已有资料。已有资料可引用，但需核对对应设备、有效期及本次变化；缺失、到期保持待核或登记问题。</text><text v-if="data.reference_suggestions?.certificate_notice" class="sm-alert">{{ data.reference_suggestions.certificate_notice }}</text><view v-if="certificateSuggestions.length" class="sm-alert sm-alert--info"><text class="sm-h3">已核验资料来源</text><text class="sm-help">首次填写已带入清单，核对后可一次确认无变化；有变化、缺失或到期的资料仍单独处理。</text><view v-for="(suggestion,index) in certificateSuggestions" :key="suggestion.id || index" class="sm-list-row"><text class="sm-text">{{ suggestion.equipment }} · {{ suggestion.reference_no }} · 有效期 {{ suggestion.valid_until || '待核' }}</text><text class="sm-help">核验来源：{{ suggestion.verified_by || '已有记录' }} · {{ formatDateTime(suggestion.verified_at) }} · {{ suggestion.source_inspection_id }}</text><button v-if="!readonly && !hasCertificate(suggestion)" class="sm-btn sm-btn--secondary sm-btn--small" @click="copyCertificate(suggestion)">引用资料，重新核对</button></view></view><button v-if="!readonly && workflow.certificate_checks.length" class="sm-btn sm-btn--secondary" @click="confirmCertificatesUnchanged">已核对所列资料均无变化</button><text v-if="!workflow.certificate_checks.length" class="sm-alert">尚无设备证书核验记录，不能自动判正常。</text><view v-for="(certificate,index) in workflow.certificate_checks" :key="certificate.id" class="workflow-event"><label class="sm-field"><text class="sm-field-label">设备 / 安全附件名称 *</text><input v-model="certificate.equipment" class="sm-input" :disabled="readonly" /></label><label class="sm-field"><text class="sm-field-label">证书或报告编号 *</text><input v-model="certificate.reference_no" class="sm-input" :disabled="readonly" /></label><label class="sm-field"><text class="sm-field-label">有效期截止日期 *</text><picker mode="date" :value="certificate.valid_until" :disabled="readonly" @change="certificate.valid_until=$event.detail.value"><view class="sm-picker">{{ certificate.valid_until || '选择日期' }}</view></picker></label><text v-if="certificate.valid_until && certificate.valid_until < data.inspection.inspection_date" class="sm-alert sm-alert--error">截至本业务日期资料已到期，请核实更新或登记问题，不能认定正常。</text><WorkflowChoice :model-value="certificate.verification" :disabled="readonly" :options="certificateOptions" @update:model-value="certificate.verification=$event;certificate.result_code=''" /><text v-if="certificate.verification==='changed'" class="sm-help">请填写变化情况并关联更新后的资料。</text><text v-if="certificate.verification==='missing'" class="sm-alert">资料缺失不能认定核验正常。可先暂存，再补资料或登记问题。</text><WorkflowCheckFields :item="certificate" :inspection-id="inspectionId" :date="data.inspection?.inspection_date" :code="'S03'" :category="2" :readonly="readonly" :hazards="data.open_hazards || []" @busy="setBusy(certificate.id,$event)" @issue-saved="issueSaved" /><button v-if="!readonly" class="sm-btn sm-btn--secondary sm-btn--small" @click="workflow.certificate_checks.splice(index,1)">移除本条资料</button></view><button v-if="!readonly" class="sm-btn sm-btn--secondary" @click="addCertificate">增加设备证书</button><view class="sm-field"><text class="sm-field-label">资料清单范围核对 *</text><WorkflowChoice v-model="workflow.certificate_scope_confirmed" :disabled="readonly" :options="scopeOptions" /><text class="sm-help">确认前应核对清单是否完整覆盖本厂站适用设备、安全附件及仪表；存在遗漏时保持待核。</text></view></view>
          <view class="sm-card"><text class="sm-h3">专用设施适用清单</text><text class="sm-help">按厂站实际设施核定。有才检查；无记“不适用”；不清楚请选择“待核实”，不默认没有。</text><text v-if="data.reference_suggestions?.facility_notice" class="sm-alert">{{ data.reference_suggestions.facility_notice }}</text><view v-if="facilitySuggestions.length" class="sm-alert sm-alert--info"><text class="sm-h3">已核定适用清单来源</text><text class="sm-help">首次填写已带入有无结论；实际存在的设施仍需本次现场检查，变化时更新适用情况。</text><text v-for="facility in facilitySuggestions" :key="facility.code" class="sm-help">{{ facility.name || facility.code }}：{{ facility.present==='yes'?'有':'无' }} · {{ facility.verified_by || '原核验人' }} · {{ formatDateTime(facility.verified_at) }}</text><button v-if="!readonly" class="sm-btn sm-btn--secondary sm-btn--small" @click="copyFacilities">引用适用清单，继续现场检查</button></view><view v-for="facility in workflow.facilities" :key="facility.code" class="sm-list-row"><text class="sm-h3">{{ facility.name }}</text><WorkflowChoice v-model="facility.present" :disabled="readonly" :options="facilityOptions" /><text v-if="facility.present==='no'" class="sm-help">本次明确核定无此设施 · 不适用</text><template v-if="facility.present==='yes'"><input v-if="facility.code==='other'" v-model="facility.name" class="sm-input" :disabled="readonly" placeholder="实际设施名称" /><WorkflowCheckFields :item="facility" :inspection-id="inspectionId" :date="data.inspection?.inspection_date" :code="'S14'" :category="2" :readonly="readonly" :hazards="data.open_hazards || []" @busy="setBusy(facility.code,$event)" @issue-saved="issueSaved" /></template></view></view>
        </template>
        <view v-for="entry in manualChecks(category.id)" :key="entry.code" class="sm-card"><text class="sm-h3">{{ entry.label }}</text><template v-if="!entry.trigger || workflow.activities[entry.trigger]==='yes'"><view v-if="entry.code==='S06'" class="sm-field"><text class="sm-field-label">是否出现不合格瓶、超量等情况 *</text><WorkflowChoice v-model="check('S06').details.exceptions" :disabled="readonly" /><label v-if="check('S06').details.exceptions==='yes'" class="sm-field"><text class="sm-field-label">实际处置记录 *</text><textarea v-model="check('S06').details.exception_handling" class="sm-textarea" :disabled="readonly" /></label></view><WorkflowCheckFields :item="check(entry.code)" :fields="checkFields[entry.code] || []" :inspection-id="inspectionId" :date="data.inspection?.inspection_date" :code="entry.code" :category="category.id" :readonly="readonly" :hazards="data.open_hazards || []" @busy="setBusy(entry.code,$event)" @issue-saved="issueSaved" /></template><text v-else-if="workflow.activities[entry.trigger]==='no'" class="sm-help">{{ entry.code==='S11'?'截至本次巡检已确认无新增安全问题报告或投诉。':'截至本次巡检未开展 · 单独记录，不计作正常。' }}</text><text v-else class="sm-alert">待确认：{{ activityOptions.find(item=>item.key===entry.trigger)?.label }}。请在上方作业与报告中点选有无。</text></view>
        <view v-if="category.id===6" class="sm-card"><text class="sm-h3">产品合格标签、气瓶警示标签</text><WorkflowCheckFields v-if="workflow.activities.filling==='yes' || workflow.activities.receiving==='yes'" :item="check('S09')" :fields="checkFields.S09" :inspection-id="inspectionId" :date="data.inspection?.inspection_date" :code="'S09'" :category="6" :readonly="readonly" :hazards="data.open_hazards || []" @busy="setBusy('S09',$event)" @issue-saved="issueSaved" /><text v-else-if="workflow.activities.filling==='no' && workflow.activities.receiving==='no'" class="sm-help">截至本次巡检无充装、气瓶收发 · 未开展。</text><text v-else class="sm-alert">待确认：是否充装、是否气瓶收发。两者有一项开展，即需核对适用标签。</text><text class="sm-help">固定及新增、变化部位的安全标志由新版原第6、17、27项检查；空满瓶标签不替代产品合格及气瓶警示标签。</text></view>
        <view v-if="category.id===7" class="sm-card"><text class="sm-h3">未关闭隐患临时管控</text><text v-if="!workflow.controls.length" class="sm-help">已读取本厂站相关隐患，无此类待核事项。</text><view v-for="control in workflow.controls" :key="control.hazard_id" class="workflow-event"><text class="sm-h3">{{ hazard(control.hazard_id)?.hazard_no || control.hazard_id }}</text><text class="sm-text">{{ hazard(control.hazard_id)?.issue_note }}</text><view class="sm-field"><text class="sm-field-label">临时管控措施是否落实 *</text><WorkflowChoice v-model="control.implemented" :disabled="readonly" :options="implementedOptions" danger-no /></view><view class="sm-field"><text class="sm-field-label">有无变化或恶化 *</text><WorkflowChoice v-model="control.changed" :disabled="readonly" /></view><label class="sm-field"><text class="sm-field-label">{{ control.implemented==='no' || control.changed==='yes'?'具体情况、处置措施 *':'实际措施及核对说明' }}</text><textarea v-model="control.note" class="sm-textarea" :disabled="readonly" /></label><SafetyEvidenceEditor v-model="control.evidence" :readonly="readonly" @busy="setBusy(control.hazard_id,$event)" /><button class="sm-btn sm-btn--secondary sm-btn--small" @click="openHazards()">查看原隐患及整改记录</button></view></view>
      </view>
      <view class="sm-card"><text class="sm-h2">保存后的七类核对状态</text><text v-if="dirty" class="sm-help">当前有未保存编辑，下列状态仍依据上次已保存资料；暂存后更新。</text><text v-if="data.complete" class="sm-alert sm-alert--info">本次七类核对内容齐全。每日检查表仍需核对当天全部记录，签认保持待签认。</text><view v-else class="sm-alert"><text v-for="(missing,index) in data.missing || []" :key="index" class="sm-text">• {{ typeof missing==='string'?missing:missing.message || missing.label }}</text></view><label v-if="!readonly" class="sm-field"><text class="sm-field-label">本次补填 / 修改说明{{ data.supplement_revision?' *':'' }}</text><textarea v-model="revisionReason" class="sm-textarea" placeholder="续填检查、增加新发生作业或说明修正依据" /></label><view class="sm-actions"><button v-if="!readonly" class="sm-btn" :disabled="saving || busyKeys.size>0" @click="save">{{ saving?'保存中…':'暂存七类核对' }}</button><button class="sm-btn sm-btn--secondary" @click="openDaily">查看每日检查表</button><button class="sm-btn sm-btn--secondary" :disabled="saving" @click="refreshSources">刷新引用及待办</button></view><text class="sm-help">暂存允许缺项，未完成不自动变正常；保存不代替上报、核对或签认。</text></view>
    </template>
  </view>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import WorkflowChoice from './WorkflowChoice.vue'
import WorkflowCheckFields from './WorkflowCheckFields.vue'
import SafetyEvidenceEditor from './SafetyEvidenceEditor.vue'
import { getInspectionWorkflow,saveInspectionWorkflow } from '@/services/safetyManagement'
import { formatDateTime,parseDateTime,openInspection,openHazards,openSafetyPage,resultLabels,showError } from './helpers'
import { categories,specialWorkTypes,checkFields,emptyCheck,hydrateWorkflow,newRowId,newSpecialEvent,confirmUnchangedCertificates } from './inspectionWorkflow'
import './safetyManagement.css'
const props=defineProps({inspectionId:{type:String,required:true},initialCategory:{type:Number,default:1}})
const emit=defineEmits(['saved','dirty','loaded'])
const data=ref({}),workflow=ref(null),loading=ref(true),saving=ref(false),error=ref(''),baseline=ref(''),revisionReason=ref(''),activeCategory=ref(props.initialCategory || 1),busyKeys=ref(new Set())
const labels={...resultLabels,covered:'已引用'},readonly=computed(()=>!data.value.permissions?.write),dirty=computed(()=>workflow.value && JSON.stringify(workflow.value)!==baseline.value)
const observedText=computed({get:()=>timeText(workflow.value?.observed_at),set:value=>{workflow.value.observed_at=value}})
const certificateSuggestions=computed(()=>data.value.reference_suggestions?.certificate_checks || [])
const facilitySuggestions=computed(()=>(data.value.reference_suggestions?.facilities || []).filter(row=>['yes','no'].includes(row.present)))
const sameDaySource=computed(()=>data.value.reference_suggestions?.same_day_source)
const activityOptions=[{key:'filling',label:'是否开展充装',help:'有则核对充装过程、计量复检和追溯。'},{key:'unloading',label:'是否开展卸车、装卸',help:'有则核对软管连接、人员过程和天气工况。'},{key:'receiving',label:'是否有气瓶收发',help:'有则核对适用的产品合格标签和气瓶警示标签。'},{key:'reports',label:'是否收到新增安全问题报告或投诉',help:'有则记录或关联实际安全问题。'}]
const specialFields=[{key:'approval',label:'作业审批 / 作业票核对'},{key:'monitor',label:'实际监护人员及安排'},{key:'measures',label:'安全措施及落实情况'}]
const certificateOptions=[{value:'unchanged',label:'已核对，无变化'},{value:'changed',label:'有变化，更新资料'},{value:'missing',label:'资料缺失 / 待核实'}]
const facilityOptions=[{value:'yes',label:'有'},{value:'no',label:'无（不适用）'},{value:'unknown',label:'待核实'}]
const scopeOptions=[{value:true,label:'已核对，清单完整'},{value:false,label:'待核实 / 尚有遗漏'}]
const implementedOptions=[{value:'yes',label:'是，已落实'},{value:'no',label:'否'},{value:'',label:'待核实'}]
function check(code){return workflow.value.checks.find(item=>item.code===code)}
watch(()=>workflow.value?.activities.reports,value=>{if(value==='yes' && check('S11'))check('S11').result_code='abnormal'})
function special(code){return workflow.value.special_work.find(item=>item.type===code)}
function chooseSpecial(code,value){if(value==='no' && special(code).events.length){uni.showToast({title:'已有作业事件，请保留已开展事实；误填且未保存的事件可先移除',icon:'none'});return}special(code).conducted=value;if(value==='yes'&&!special(code).events.length)special(code).events.push(newSpecialEvent())}
function savedEvent(id){return(data.value.workflow?.special_work || []).some(type=>(type.events || []).some(event=>event.id===id))}
function removeEvent(code,index){uni.showModal({title:'移除这条作业',content:'仅在本次填写有误时移除，已经开展的作业应保留。',success:result=>{if(result.confirm)special(code).events.splice(index,1)}})}
function timeText(value){return typeof value==='number'?formatDateTime(value):value || ''}
function originalChecks(category){return(data.value.inspection?.items || []).filter(item=>Number(item.category_code)===category)}
function categoryPendingCount(category){return(data.value.items || []).filter(item=>Number(item.category_code)===category && item.missing?.length).length}
function categoryCoverage(category){return(data.value.coverage || []).filter(item=>Number(data.value.definitions?.supplement_definitions?.find(def=>def.code===item.code)?.category_code)===category)}
function hazard(id){return(data.value.open_hazards || []).find(item=>item._id===id)}
function setBusy(key,value){if(value)busyKeys.value.add(key);else busyKeys.value.delete(key)}
function manualChecks(category){return({2:[{code:'S13a',label:'装卸软管及连接',trigger:'unloading'}],3:[{code:'S04',label:'本班人员资格及交底'},{code:'S06',label:'充装过程及追溯',trigger:'filling'},{code:'S13b',label:'装卸人员及过程',trigger:'unloading'}],4:[{code:'S13c',label:'装卸天气与异常工况',trigger:'unloading'}],7:[{code:'S11',label:'新增安全报告 / 投诉',trigger:'reports'}]})[category] || []}
function addCertificate(){workflow.value.certificate_checks.push({...emptyCheck(),id:newRowId(),equipment:'',reference_no:'',valid_until:'',verification:''})}
function hasCertificate(source){return workflow.value.certificate_checks.some(row=>row.equipment===source.equipment && row.reference_no===source.reference_no)}
function confirmCertificatesUnchanged(){const count=confirmUnchangedCertificates(workflow.value.certificate_checks,data.value.inspection.inspection_date);uni.showToast({title:count?`已确认${count}项资料无变化`:'尚无有效且资料齐全的可确认项目',icon:'none'})}
function copyCertificate(source){workflow.value.certificate_checks.push({...emptyCheck(),...JSON.parse(JSON.stringify(source)),id:newRowId(),verification:'',result_code:'',note:'',hazard_ids:[]})}
function copySameDay(){
 const prior=data.value.reference_suggestions?.same_day_workflow;if(!prior || !sameDaySource.value)return
 const apply=()=>{
  const snapshot=JSON.parse(JSON.stringify(prior))
  for(const type of snapshot.special_work || []){if(type.conducted!=='yes')continue;const target=special(type.type);target.conducted='yes';for(const event of type.events || [])if(!target.events.some(existing=>existing.id===event.id))target.events.push({...emptyCheck(),...event})}
  for(const key of ['filling','unloading','receiving','reports'])if(snapshot.activities?.[key]==='yes')workflow.value.activities[key]='yes'
  for(const row of snapshot.checks || []){if(!['S06','S09','S11','S13a','S13b','S13c'].includes(row.code) || !row.result_code)continue;const index=workflow.value.checks.findIndex(item=>item.code===row.code);if(index>=0 && !workflow.value.checks[index].result_code)workflow.value.checks[index]={...emptyCheck(row.code),...row}}
  workflow.value.reference_sources=[...(workflow.value.reference_sources || []).filter(source=>source.inspection_id!==sameDaySource.value.inspection_id),JSON.parse(JSON.stringify(sameDaySource.value))]
 }
 apply();uni.showToast({title:'已引用已发生事项，请核对本次变化',icon:'none'})
}
function copyFacilities(){for(const source of facilitySuggestions.value){const target=workflow.value.facilities.find(row=>row.code===source.code);if(target && !target.result_code){target.present=source.present;target.name=source.name || target.name;target.note=`引用已核定清单：${source.source_inspection_id || ''}，${formatDateTime(source.verified_at)}`}}}
function accept(result){data.value=result;workflow.value=hydrateWorkflow(result);baseline.value=JSON.stringify(workflow.value);revisionReason.value='';emit('loaded',result)}
async function load(){if(!props.inspectionId)return;loading.value=true;error.value='';try{accept(await getInspectionWorkflow({inspection_id:props.inspectionId}))}catch(err){error.value=err.message}finally{loading.value=false}}
function payloadWorkflow(){const result=JSON.parse(JSON.stringify(workflow.value));result.observed_at=typeof result.observed_at==='number'?result.observed_at:parseDateTime(result.observed_at);if(!Number.isFinite(result.observed_at)||!result.observed_at)throw new Error('请填写本次事实截至时间');for(const row of result.special_work){for(const event of row.events){for(const key of ['started_at','ended_at']){if(event[key]){event[key]=typeof event[key]==='number'?event[key]:parseDateTime(event[key]);if(!Number.isFinite(event[key]))throw new Error('请核对特殊作业起止时间')}}}}return result}
async function save(){if(readonly.value || saving.value)return;saving.value=true;try{if(busyKeys.value.size)throw new Error('请等待证据上传完成');const result=await saveInspectionWorkflow({inspection_id:props.inspectionId,expected_revision:data.value.supplement_revision || 0,source_revision:data.value.source_revision || data.value.inspection?.revision || 1,revision_reason:revisionReason.value,workflow:payloadWorkflow()});accept(result);emit('saved',result);uni.showToast({title:'七类核对已暂存',icon:'success'})}catch(err){showError(err)}finally{saving.value=false}}
async function issueSaved(){revisionReason.value=revisionReason.value || '登记本次问题并关联检查事实';await save()}
function refreshSources(){if(!dirty.value)return load();uni.showModal({title:'刷新七类核对',content:'刷新会替换当前尚未保存的编辑。可先暂存；如遇版本冲突，请保留修改内容后再刷新核对。',success:result=>{if(result.confirm)load()}})}
async function openDaily(){if(dirty.value){uni.showModal({title:'尚有未保存核对',content:'请先暂存，再查看包含本次编辑的每日检查表。',showCancel:false});return}openSafetyPage('daily',{date:data.value.inspection?.inspection_date})}
function focusCategory(value){activeCategory.value=Number(value)||1}
watch(dirty,value=>emit('dirty',Boolean(value)))
watch(()=>props.inspectionId,load,{immediate:true})
defineExpose({save,load,focusCategory,hasUnsavedChanges:dirty})
</script>
<style scoped>
.workflow-editor{color:#213547}.workflow-switch{padding:18rpx 0;border-bottom:1rpx solid #e2e8f0}.workflow-reference{display:flex;gap:14rpx;align-items:flex-start;margin:12rpx 0}.workflow-reference .sm-tag{flex:none}.workflow-reference .sm-text{font-size:23rpx}.workflow-event{margin:20rpx 0;padding:22rpx;border:1rpx solid #dce5ec;background:#f8fafc;border-radius:16rpx}.workflow-editor :deep(button::after){border:0}
</style>
